const payload = $input.first().json;
const data = payload.data || payload;

return [{
  json: {
    subject: `🎉 Order Delivered! #${data.trackingNumber}`,
    customerNotification: {
      title: 'Order Delivered Successfully!',
      message: `Your medicine order #${data.trackingNumber} has been delivered by ${data.riderName || 'your rider'}. You earned ${data.loyaltyEarned || 0} loyalty points!`,
      recipientEmail: data.userEmail,
      recipientName: data.userName,
      loyaltyEarned: data.loyaltyEarned || 0,
      totalAmount: data.totalAmount || 0
    },
    body: `Order ${data.trackingNumber} has been marked as DELIVERED.\n\n` +
          `Customer: ${data.userName || 'N/A'} (${data.userEmail || 'N/A'})\n` +
          `Delivered by: ${data.riderName || 'Rider'} (ID: ${data.riderId})\n` +
          `Total Amount: ₹${data.totalAmount?.toFixed(2) || '0.00'}\n` +
          `Loyalty Points Awarded: ${data.loyaltyEarned || 0}\n\n` +
          `Delivered at: ${payload.timestamp || new Date().toISOString()}`,
    orderId: data.orderId,
    trackingNumber: data.trackingNumber,
    riderId: data.riderId,
    userEmail: data.userEmail,
    totalAmount: data.totalAmount,
    loyaltyEarned: data.loyaltyEarned
  }
}];
